:root {
  --rose: #c0395e;
  --rose-light: #f7d6e0;
  --rose-pale: #fdf0f4;
  --gold: #b8860b;
  --cream: #faf7f2;
  --bark: #2d1f1a;
  --bark-mid: #5a3e35;
  --mist: #8a7c75;
  --white: #ffffff;
  --border: rgba(192,57,94,0.15);
  --font-display: 'Cormorant Garamond', Georgia, serif;
  --font-body: 'DM Sans', sans-serif;
}

*, *::before, *::after { margin:0; padding:0; box-sizing:border-box; text-decoration:none; }

html, body { height:100%; overflow:hidden; font-family:var(--font-body); background:var(--cream); color:var(--bark); }

.shell { display:flex; flex-direction:column; height:100vh; }

header {
  background:rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  border-bottom:1px solid var(--border);
  display:flex; align-items:center; justify-content:space-between;
  padding:0 3rem; height:64px; flex-shrink:0; position:relative; z-index:100;
}
.logo { font-family:var(--font-display); font-size:2rem; font-weight:500; color:var(--bark); letter-spacing:0.05em; }
.logo span { color:var(--rose); }
nav { display:flex; gap:0.25rem; }
nav button {
  background:none; border:none; cursor:pointer;
  font-family:var(--font-body); font-size:0.8rem; font-weight:400;
  letter-spacing:0.12em; text-transform:uppercase; color:var(--mist);
  padding:0.5rem 1rem; border-radius:2rem; transition:all 0.2s;
}
nav button:hover { color:var(--bark); }
nav button.active { background:var(--rose-pale); color:var(--rose); font-weight:500; }
.header-right { display:flex; align-items:center; gap:1.25rem; }
.icon-btn { background:none; border:none; cursor:pointer; color:var(--mist); font-size:1.05rem; transition:color 0.2s; position:relative; }
.icon-btn:hover { color:var(--rose); }
.cart-badge {
  position:absolute; top:-6px; right:-6px;
  background:var(--rose); color:#fff; font-size:0.6rem; font-weight:500;
  width:16px; height:16px; border-radius:50%; display:flex; align-items:center; justify-content:center;
}

.pages { flex:1; overflow:hidden; position:relative; }
.page { position:absolute; inset:0; overflow:auto; display:none; opacity:0; transition:opacity 0.35s; }
.page.active { display:block; opacity:1; }
.page::-webkit-scrollbar { width:4px; }
.page::-webkit-scrollbar-track { background:transparent; }
.page::-webkit-scrollbar-thumb { background:var(--rose-light); border-radius:2px; }

/* HOME with background image */
.home-wrap {
  height:100%; display:flex;
  background-image: url('data:image/jpeg;base64,');
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  position: relative;
}
.home-wrap::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, rgba(253,240,244,0.96) 0%, rgba(253,240,244,0.85) 50%, rgba(253,240,244,0.3) 100%);
  z-index: 0;
}
.home-left {
  flex:0 0 55%; display:flex; flex-direction:column;
  justify-content:center; padding:4rem 5rem;
  position: relative; z-index: 1;
}
.home-right {
  flex:1; position:relative; overflow:hidden;
  display:flex; align-items:center; justify-content:center;
  z-index: 1;
}
.home-eyebrow {
  font-size:0.7rem; letter-spacing:0.3em; text-transform:uppercase;
  color:var(--rose); margin-bottom:1.5rem; display:flex; align-items:center; gap:0.75rem;
}
.home-eyebrow::before { content:''; display:block; width:2rem; height:1px; background:var(--rose); }
.home-title {
  font-family:var(--font-display); font-size:5.5rem; font-weight:300;
  line-height:1.05; color:var(--bark); margin-bottom:1.5rem;
}
.home-title em { font-style:italic; color:var(--rose); }
.home-sub { font-size:0.95rem; color:var(--mist); line-height:1.75; max-width:38ch; margin-bottom:2.5rem; }
.home-actions { display:flex; gap:1rem; align-items:center; }
.btn-primary {
  background:var(--bark); color:var(--white);
  border:none; padding:0.85rem 2.5rem; border-radius:3rem; cursor:pointer;
  font-family:var(--font-body); font-size:0.82rem; letter-spacing:0.12em; text-transform:uppercase;
  font-weight:500; transition:all 0.2s;
}
.btn-primary:hover { background:var(--rose); }
.btn-ghost {
  background:none; border:1px solid var(--bark); color:var(--bark);
  padding:0.85rem 2rem; border-radius:3rem; cursor:pointer;
  font-family:var(--font-body); font-size:0.82rem; letter-spacing:0.12em; text-transform:uppercase;
  font-weight:400; transition:all 0.2s;
}
.btn-ghost:hover { border-color:var(--rose); color:var(--rose); }
.home-bg-shape {
  position:absolute; inset:0;
  background: radial-gradient(ellipse at 60% 50%, rgba(192,57,94,0.08) 0%, transparent 70%);
}
.home-flower-grid {
  display:grid; grid-template-columns:1fr 1fr; gap:1rem;
  padding:2rem; position:relative; z-index:1;
}
.flower-card {
  border-radius:1.5rem; overflow:hidden; position:relative;
  background:rgba(247,214,224,0.7); backdrop-filter: blur(4px);
}
.flower-card:nth-child(1) { height:220px; }
.flower-card:nth-child(2) { height:160px; margin-top:3rem; }
.flower-card:nth-child(3) { height:160px; margin-top:-2rem; }
.flower-card:nth-child(4) { height:220px; }
.flower-card-inner {
  width:100%; height:100%; display:flex; align-items:center; justify-content:center;
  font-size:4rem; background:linear-gradient(135deg, rgba(253,240,244,0.8), rgba(247,214,224,0.8));
}
.flower-stats {
  display:flex; gap:3rem; margin-top:3rem;
  padding-top:2rem; border-top:1px solid var(--border);
}
.stat { display:flex; flex-direction:column; }
.stat-num { font-family:var(--font-display); font-size:2.2rem; font-weight:400; color:var(--bark); }
.stat-label { font-size:0.72rem; text-transform:uppercase; letter-spacing:0.12em; color:var(--mist); margin-top:0.2rem; }

/* ABOUT */
.about-wrap { padding:3rem 4rem; max-width:1200px; margin:0 auto; }
.section-title {
  font-family:var(--font-display); font-size:3rem; font-weight:300;
  color:var(--bark); margin-bottom:0.5rem;
}
.section-title span { color:var(--rose); font-style:italic; }
.section-sub { font-size:0.85rem; color:var(--mist); letter-spacing:0.15em; text-transform:uppercase; margin-bottom:3rem; }
.about-grid { display:grid; grid-template-columns:1fr 1fr; gap:3rem; align-items:start; }
.about-visual {
  background:linear-gradient(145deg, var(--rose-pale), var(--rose-light));
  border-radius:2rem; height:380px;
  display:flex; align-items:center; justify-content:center;
  font-size:8rem; position:relative; overflow:hidden;
}
.about-badge {
  position:absolute; bottom:2rem; left:2rem;
  background:rgba(45,31,26,0.85); backdrop-filter:blur(8px);
  color:var(--white); padding:0.75rem 1.5rem; border-radius:0.75rem;
  font-size:0.8rem; letter-spacing:0.1em; text-transform:uppercase;
}
.about-content h3 { font-family:var(--font-display); font-size:2rem; font-weight:400; margin-bottom:1rem; color:var(--bark); }
.about-content p { font-size:0.9rem; color:var(--mist); line-height:1.8; margin-bottom:2rem; }
.feature-grid { display:grid; grid-template-columns:1fr 1fr; gap:1rem; }
.feature-card {
  background:var(--white); border:1px solid var(--border);
  border-radius:1rem; padding:1.25rem; display:flex; flex-direction:column; gap:0.5rem;
}
.feature-icon { font-size:1.4rem; color:var(--rose); }
.feature-title { font-size:0.82rem; font-weight:500; text-transform:uppercase; letter-spacing:0.1em; color:var(--bark); }
.feature-desc { font-size:0.78rem; color:var(--mist); line-height:1.6; }

/* PRODUCTS */
.products-wrap { padding:2rem 3rem; }
.products-header { display:flex; justify-content:space-between; align-items:flex-end; margin-bottom:2rem; }
.filter-row { display:flex; gap:0.5rem; }
.filter-btn {
  background:var(--white); border:1px solid var(--border); cursor:pointer;
  font-family:var(--font-body); font-size:0.75rem; letter-spacing:0.1em;
  text-transform:uppercase; color:var(--mist); padding:0.5rem 1.25rem;
  border-radius:2rem; transition:all 0.2s;
}
.filter-btn.active, .filter-btn:hover { background:var(--rose); color:var(--white); border-color:var(--rose); }
.product-grid {
  display:grid; grid-template-columns:repeat(3,1fr);
  gap:1.5rem;
}
.product-card {
  background:var(--white); border:1px solid var(--border); border-radius:1.5rem;
  overflow:hidden; cursor:pointer; transition:all 0.25s; position:relative;
}
.product-card:hover { transform:translateY(-4px); box-shadow:0 16px 40px rgba(192,57,94,0.12); border-color:var(--rose); }
.product-img {
  height:200px; background:linear-gradient(135deg, var(--rose-pale), var(--rose-light));
  display:flex; align-items:center; justify-content:center; font-size:5rem;
  position:relative; overflow:hidden;
}
.product-overlay {
  position:absolute; inset:0;
  background:rgba(45,31,26,0.7);
  display:flex; align-items:center; justify-content:center; gap:0.75rem;
  opacity:0; transition:opacity 0.25s;
}
.product-card:hover .product-overlay { opacity:1; }
.overlay-btn {
  background:var(--white); border:none; cursor:pointer;
  width:40px; height:40px; border-radius:50%;
  display:flex; align-items:center; justify-content:center;
  font-size:0.9rem; color:var(--bark); transition:all 0.2s;
}
.overlay-btn:hover { background:var(--rose); color:var(--white); }
.product-body { padding:1.25rem; }
.product-tag {
  display:inline-block; font-size:0.65rem; text-transform:uppercase;
  letter-spacing:0.15em; color:var(--rose); margin-bottom:0.5rem;
}
.product-name { font-family:var(--font-display); font-size:1.25rem; font-weight:400; color:var(--bark); margin-bottom:0.3rem; }
.product-desc { font-size:0.78rem; color:var(--mist); line-height:1.6; margin-bottom:0.75rem; }
.product-footer { display:flex; justify-content:space-between; align-items:center; }
.stars { color:#e8b84b; font-size:0.7rem; }
.price { font-family:var(--font-display); font-size:1.3rem; color:var(--rose); font-weight:500; }
.product-badge {
  position:absolute; top:1rem; left:1rem;
  background:var(--bark); color:var(--white);
  font-size:0.65rem; font-weight:500; text-transform:uppercase; letter-spacing:0.1em;
  padding:0.25rem 0.75rem; border-radius:2rem;
}

/* REVIEWS */
.review-wrap { padding:3rem 4rem; max-width:1100px; margin:0 auto; }
.review-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:1.5rem; margin-top:0; }
.review-card {
  background:var(--white); border:1px solid var(--border);
  border-radius:1.5rem; padding:2rem; position:relative;
}
.quote-mark {
  font-family:var(--font-display); font-size:5rem; color:var(--rose-light);
  line-height:1; position:absolute; top:1rem; right:1.5rem;
}
.review-stars { color:#e8b84b; font-size:0.8rem; margin-bottom:1rem; }
.review-text { font-size:0.88rem; color:var(--mist); line-height:1.8; margin-bottom:1.5rem; font-style:italic; }
.review-user { display:flex; align-items:center; gap:0.75rem; }
.user-avatar {
  width:44px; height:44px; border-radius:50%;
  background:linear-gradient(135deg, var(--rose-light), var(--rose));
  display:flex; align-items:center; justify-content:center;
  font-family:var(--font-display); font-size:1.1rem; color:var(--white); font-weight:500;
}
.user-name { font-size:0.88rem; font-weight:500; color:var(--bark); }
.user-role { font-size:0.75rem; color:var(--mist); text-transform:uppercase; letter-spacing:0.1em; }
.rating-summary {
  background:linear-gradient(135deg, var(--rose-pale), var(--rose-light));
  border-radius:1.5rem; padding:2.5rem 3rem; margin-bottom:2.5rem;
  display:flex; align-items:center; gap:3rem;
}
.rating-big { font-family:var(--font-display); font-size:5rem; font-weight:300; color:var(--bark); line-height:1; }
.rating-detail { flex:1; }
.rating-label { font-size:0.75rem; text-transform:uppercase; letter-spacing:0.15em; color:var(--mist); margin-bottom:0.75rem; }
.rating-bar { display:flex; align-items:center; gap:0.75rem; margin-bottom:0.4rem; }
.rating-bar-label { font-size:0.75rem; color:var(--mist); width:1rem; }
.bar-track { flex:1; height:4px; background:rgba(192,57,94,0.15); border-radius:2px; }
.bar-fill { height:100%; background:var(--rose); border-radius:2px; }
.rating-count { font-size:0.75rem; color:var(--mist); }

/* CONTACT */
.contact-wrap { padding:3rem 4rem; display:grid; grid-template-columns:1fr 1fr; gap:3rem; max-width:1200px; margin:0 auto; }
.contact-left p { font-size:0.88rem; color:var(--mist); line-height:1.8; margin-bottom:2rem; }
.contact-info-list { display:flex; flex-direction:column; gap:1rem; margin-bottom:2rem; }
.contact-info-item {
  display:flex; align-items:center; gap:1rem;
  background:var(--white); border:1px solid var(--border);
  border-radius:1rem; padding:1rem 1.25rem;
}
.contact-info-icon { color:var(--rose); font-size:1.1rem; width:20px; }
.contact-info-label { font-size:0.7rem; text-transform:uppercase; letter-spacing:0.12em; color:var(--mist); }
.contact-info-value { font-size:0.88rem; color:var(--bark); font-weight:500; }
.social-row { display:flex; gap:0.75rem; }
.social-btn {
  width:40px; height:40px; border-radius:50%; border:1px solid var(--border);
  background:var(--white); cursor:pointer; display:flex; align-items:center; justify-content:center;
  font-size:0.9rem; color:var(--mist); transition:all 0.2s;
}
.social-btn:hover { background:var(--rose); color:var(--white); border-color:var(--rose); }
.contact-form { background:var(--white); border:1px solid var(--border); border-radius:1.5rem; padding:2.5rem; }
.contact-form h3 { font-family:var(--font-display); font-size:1.75rem; font-weight:400; margin-bottom:1.5rem; color:var(--bark); }
.form-row { display:grid; grid-template-columns:1fr 1fr; gap:1rem; margin-bottom:1rem; }
.form-field { display:flex; flex-direction:column; gap:0.4rem; margin-bottom:1rem; }
.form-field label { font-size:0.72rem; text-transform:uppercase; letter-spacing:0.12em; color:var(--mist); }
.form-field input, .form-field textarea {
  border:1px solid var(--border); border-radius:0.75rem; padding:0.85rem 1rem;
  font-family:var(--font-body); font-size:0.88rem; color:var(--bark);
  background:var(--cream); outline:none; transition:border-color 0.2s; resize:none;
}
.form-field input:focus, .form-field textarea:focus { border-color:var(--rose); }

/* MODAL */
.modal-bg {
  position:fixed; inset:0; background:rgba(45,31,26,0.6);
  backdrop-filter:blur(4px); z-index:500;
  display:flex; align-items:center; justify-content:center;
  opacity:0; pointer-events:none; transition:opacity 0.3s;
}
.modal-bg.open { opacity:1; pointer-events:all; }
.modal-box {
  background:var(--white); border-radius:2rem;
  width:680px; max-width:95vw; max-height:88vh; overflow:auto;
  transform:scale(0.95); transition:transform 0.3s;
  position:relative;
}
.modal-bg.open .modal-box { transform:scale(1); }
.modal-close {
  position:absolute; top:1.25rem; right:1.25rem; z-index:10;
  background:var(--cream); border:none; border-radius:50%; width:36px; height:36px;
  cursor:pointer; font-size:1rem; color:var(--mist); display:flex; align-items:center; justify-content:center;
}
.modal-close:hover { background:var(--rose); color:var(--white); }
.modal-inner { display:grid; grid-template-columns:1fr 1.1fr; }
.modal-img {
  height:100%; min-height:360px; background:linear-gradient(145deg, var(--rose-pale), var(--rose-light));
  border-radius:2rem 0 0 2rem; display:flex; align-items:center; justify-content:center; font-size:8rem;
}
.modal-content { padding:2.5rem; }
.modal-tag { font-size:0.7rem; text-transform:uppercase; letter-spacing:0.15em; color:var(--rose); margin-bottom:0.5rem; }
.modal-title { font-family:var(--font-display); font-size:2rem; font-weight:400; color:var(--bark); margin-bottom:0.5rem; }
.modal-price { font-family:var(--font-display); font-size:1.8rem; color:var(--rose); font-weight:400; margin-bottom:1rem; }
.modal-desc { font-size:0.83rem; color:var(--mist); line-height:1.8; margin-bottom:1.5rem; }
.modal-details { display:flex; flex-direction:column; gap:0.5rem; margin-bottom:1.5rem; }
.modal-detail { display:flex; align-items:center; gap:0.75rem; font-size:0.8rem; color:var(--mist); }
.modal-detail i { color:var(--rose); width:16px; }
.qty-row { display:flex; align-items:center; gap:1rem; margin-bottom:1.5rem; }
.qty-label { font-size:0.75rem; text-transform:uppercase; letter-spacing:0.1em; color:var(--mist); }
.qty-ctrl { display:flex; align-items:center; gap:0.75rem; }
.qty-btn {
  width:32px; height:32px; border-radius:50%; border:1px solid var(--border);
  background:var(--cream); cursor:pointer; font-size:1.1rem; color:var(--bark); display:flex; align-items:center; justify-content:center;
  transition:all 0.2s;
}
.qty-btn:hover { background:var(--rose); color:var(--white); border-color:var(--rose); }
.qty-num { font-family:var(--font-display); font-size:1.4rem; min-width:2rem; text-align:center; color:var(--bark); }

/* TOAST */
.toast {
  position:fixed; bottom:2rem; right:2rem;
  background:var(--bark); color:var(--white);
  padding:1rem 1.5rem; border-radius:1rem;
  font-size:0.85rem; display:flex; align-items:center; gap:0.75rem;
  transform:translateY(4rem); opacity:0; transition:all 0.3s; z-index:1000;
}
.toast.show { transform:translateY(0); opacity:1; }
.toast i { color:var(--rose); }

/* CART SIDEBAR */
.cart-sidebar {
  position:fixed; right:0; top:0; bottom:0; width:380px;
  background:var(--white); border-left:1px solid var(--border);
  z-index:600; transform:translateX(100%); transition:transform 0.3s;
  display:flex; flex-direction:column;
}
.cart-sidebar.open { transform:translateX(0); }
.cart-overlay { position:fixed; inset:0; background:rgba(0,0,0,0.3); z-index:599; display:none; }
.cart-overlay.open { display:block; }
.cart-header { padding:1.5rem 1.5rem 1rem; border-bottom:1px solid var(--border); display:flex; justify-content:space-between; align-items:center; }
.cart-title { font-family:var(--font-display); font-size:1.5rem; font-weight:400; color:var(--bark); }
.cart-close { background:none; border:none; cursor:pointer; color:var(--mist); font-size:1.1rem; }
.cart-items { flex:1; overflow:auto; padding:1rem 1.5rem; }
.cart-empty { text-align:center; padding:3rem; color:var(--mist); font-size:0.88rem; }
.cart-empty i { font-size:3rem; display:block; margin-bottom:1rem; color:var(--rose-light); }
.cart-item { display:flex; gap:1rem; padding:1rem 0; border-bottom:1px solid var(--border); }
.cart-item-icon { width:56px; height:56px; background:var(--rose-pale); border-radius:0.75rem; display:flex; align-items:center; justify-content:center; font-size:1.8rem; flex-shrink:0; }
.cart-item-info { flex:1; }
.cart-item-name { font-size:0.88rem; font-weight:500; color:var(--bark); }
.cart-item-price { font-size:0.82rem; color:var(--rose); margin-top:0.2rem; }
.cart-item-qty { font-size:0.78rem; color:var(--mist); margin-top:0.2rem; }
.cart-item-remove { background:none; border:none; cursor:pointer; color:var(--mist); font-size:0.85rem; align-self:flex-start; padding-top:0.1rem; }
.cart-item-remove:hover { color:var(--rose); }
.cart-footer { padding:1.5rem; border-top:1px solid var(--border); }
.cart-total { display:flex; justify-content:space-between; margin-bottom:1.25rem; }
.cart-total-label { font-size:0.82rem; color:var(--mist); text-transform:uppercase; letter-spacing:0.1em; }
.cart-total-val { font-family:var(--font-display); font-size:1.5rem; color:var(--bark); }